namespace optiling {
const uint32_t MAX_BLOCKS = 32;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvStandard2dSquareInputAsymmetricKernelCustomTiling tiling;

    const auto *inShape = context->GetInputShape(0);
    const auto *wShape = context->GetInputShape(1);
    if (inShape == nullptr || wShape == nullptr) {
        return ge::GRAPH_FAILED;
    }

    auto in = inShape->GetOriginShape();
    auto w  = wShape->GetOriginShape();
    if (in.GetDimNum() != 4 || w.GetDimNum() != 4) {
        return ge::GRAPH_FAILED;
    }

    uint32_t N  = static_cast<uint32_t>(in.GetDim(0));
    uint32_t Cin  = static_cast<uint32_t>(in.GetDim(1));
    uint32_t Hin  = static_cast<uint32_t>(in.GetDim(2));
    uint32_t Win  = static_cast<uint32_t>(in.GetDim(3));

    uint32_t Cout = static_cast<uint32_t>(w.GetDim(0));
    uint32_t WCin = static_cast<uint32_t>(w.GetDim(1));
    uint32_t kH   = static_cast<uint32_t>(w.GetDim(2));
    uint32_t kW   = static_cast<uint32_t>(w.GetDim(3));

    if (WCin != Cin) {
        return ge::GRAPH_FAILED;
    }

    // assume stride=1, padding=0, dilation=1
    uint32_t outH = Hin >= kH ? (Hin - kH + 1) : 0;
    uint32_t outW = Win >= kW ? (Win - kW + 1) : 0;

    uint32_t blockDim = (Cout < MAX_BLOCKS) ? Cout : MAX_BLOCKS;
    if (blockDim == 0) blockDim = 1;
    context->SetBlockDim(blockDim);

    uint32_t ocPerBlock = (Cout + blockDim - 1) / blockDim;

    tiling.set_n(N);
    tiling.set_c_in(Cin);
    tiling.set_h(Hin);
    tiling.set_w(Win);
    tiling.set_c_out(Cout);
    tiling.set_kH(kH);
    tiling.set_kW(kW);
    tiling.set_outH(outH);
    tiling.set_outW(outW);
    tiling.set_ocPerBlock(ocPerBlock);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *workspaceSizes = context->GetWorkspaceSizes(1);
    workspaceSizes[0] = 0;

    return ge::GRAPH_SUCCESS;
}
}

