#include <torch/library.h>
#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor conv2d_custom_impl_npu(const at::Tensor& x, const at::Tensor& weight) {
    auto N = x.size(0);
    auto Cin = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);
    auto Cout = weight.size(0);
    auto kH = weight.size(2);
    auto kW = weight.size(3);
    // stride=1, padding=0, dilation=1
    auto outH = H - kH + 1;
    auto outW = W - kW + 1;
    at::Tensor y = at::empty({N, Cout, outH, outW}, x.options());
    EXEC_NPU_CMD(aclnnConvStandard2dSquareInputAsymmetricKernelCustom, x, weight, y);
    return y;
}

TORCH_LIBRARY_IMPL(myops, PrivateUse1, m) {
    m.impl("conv_standard_2d_square_input_asymmetric_kernel_custom", &conv2d_custom_impl_npu);
}

